<?php

// Connection to the Admin Panel REST API (docs/API_CONTRACT.md). Every secret is read from the environment / key paths;
// nothing here is generated by the application.
return [
    // e.g. https://admin.internal.example/api/v1  (the path part is part of the signed PATH)
    'base_url' => env('ADMIN_API_BASE_URL'),

    // Shared HMAC secret (same value as API_HMAC_SECRET on the Admin side).
    'hmac_secret' => env('ADMIN_API_HMAC_SECRET'),

    // Admin's RSA public key (vob_public.pem) and its key id, used to wrap the AES key of X-Auth-Data.
    'rsa_public_key_path' => env('ADMIN_API_RSA_PUBLIC_KEY_PATH', 'storage/app/keys/vob_public.pem'),
    'rsa_key_id' => env('ADMIN_API_RSA_KEY_ID', 'k1'),

    'timeout' => (int) env('ADMIN_API_TIMEOUT', 15),
    'connect_timeout' => (int) env('ADMIN_API_CONNECT_TIMEOUT', 5),
    // Extra attempts for connection failures / 5xx on idempotent calls (GET, PUT, DELETE) only. Each attempt is re-signed.
    'retries' => (int) env('ADMIN_API_RETRIES', 2),
    'retry_sleep_ms' => (int) env('ADMIN_API_RETRY_SLEEP_MS', 200),

    // api_logs retention for `logs:purge-api`.
    'log_retention_months' => (int) env('API_LOG_RETENTION_MONTHS', 2),
];
